<?php session_start();require 'db.php';$error='';if(isset($_SESSION['last_activity'])&&time()-$_SESSION['last_activity']>900){$_SESSION=[];session_destroy();session_start();$error='Session expired. Please sign in again.';}if($_SERVER['REQUEST_METHOD']==='POST'){$username=trim($_POST['username']??'');$password=$_POST['password']??'';$stmt=$mysqli->prepare('SELECT id,name,password_hash,role FROM users WHERE username=?');$stmt->bind_param('s',$username);$stmt->execute();$stmt->bind_result($id,$name,$hash,$role);if($stmt->fetch()&&password_verify($password,$hash)){session_regenerate_id(true);$_SESSION['user_id']=$id;$_SESSION['name']=$name;$_SESSION['role']=$role;$_SESSION['last_activity']=time();header('Location: dashboard.php');exit;}else$error='Invalid username or password.';$stmt->close();}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Login</title></head><body><h1>StudentHub Login</h1><p><?=htmlspecialchars($error)?></p><form method="post"><label>Username <input name="username" required></label><br><label>Password <input type="password" name="password" required></label><br><button>Login</button></form></body></html>